107	        for (JsonNode node : history.get("allocations")) {
108	            if (allocationKey.equals(node.get("allocationKey").asText())) {
109	                return node;
110	            }
111	        }
112	        throw new IllegalStateException("allocation not found: " + allocationKey);
113	    }
