                } catch (ApiException e) {
                    return e.status().value();
                }
            }));
        }
        gate.countDown();
        int s1 = futures.get(0).get(30, TimeUnit.SECONDS);
        int s2 = futures.get(1).get(30, TimeUnit.SECONDS);
        pool.shutdown();
        assertEquals(1, (s1 == 200 ? 1 : 0) + (s2 == 200 ? 1 : 0),
